--
-- Table structure for table `ai_analytics_reports`
--

CREATE TABLE `ai_analytics_reports` (
    `id` int(11) NOT NULL,
    `report_type` enum(
        'incident_analysis',
        'trend_report',
        'predictive_forecast',
        'resource_allocation'
    ) NOT NULL,
    `report_title` varchar(255) NOT NULL,
    `date_range_start` date NOT NULL,
